import{_ as s,l,o as e,c as o,v as t,p as n,x as r,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"亚分辨辅助图形 SRAF","description":"","frontmatter":{"title":"亚分辨辅助图形 SRAF","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/sraf-assist.md","filePath":"litho/sraf-assist.md","lastUpdated":1789023840000}'),A={name:"litho/sraf-assist.md"};function d(c,a,B,m,_,f){const i=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="亚分辨辅助图形-sraf" tabindex="-1">亚分辨辅助图形 SRAF <a class="header-anchor" href="#亚分辨辅助图形-sraf" aria-label="Permalink to &quot;亚分辨辅助图形 SRAF&quot;">​</a></h1><div class="epigraph"><p>密线靠邻线提供衍射环境；孤立线没有邻居，焦深与剂量窗先关。亚分辨辅助杆把环境伪装成「有邻居」，自己却印不出来。</p><footer>—— 据 Mack 对 scattering bars / 辅助图形的论述，以及 Liebchen 等对 SRAF 放置与可印性约束的计算光刻表述</footer></div><p><a href="/litho/alt-psm">上一课</a>用 0/π 交替把密线暗区做黑。缺口是孤立与半孤立：同一层里疏的线、线端、孔，工艺窗与密阵列对不上，交替染色也帮不上没有邻居的开口。本课钉亚分辨辅助图形（SRAF、scattering bars）。吸收体厚度让细杆先感到三维，留给<a href="/litho/mask-3d-effect">掩模 3D</a>，本课仍以薄屏为主。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RET 把密栅的 \\(k_1\\) 往下推之后，孤立线的空中像仍接近「单开口衍射」：焦深窄、与密线的最佳剂量错开，E–D 重叠窗口被孤立图形切掉。上一课的相位边只出现在相邻开口之间；孤立线两侧若都是大片铬或大片石英，没有相消环境可借。</p><p>缺口因此是在主图形旁插入印不出来的细特征，改变主图形的局部频谱，而不是再做一次交替染色。没有 SRAF，OPC 只能加宽或加锤头，窗口仍按孤立线的焦深走。</p><h3 id="印不出来是规格-不是意外" tabindex="-1">印不出来是规格，不是意外 <a class="header-anchor" href="#印不出来是规格-不是意外" aria-label="Permalink to &quot;印不出来是规格，不是意外&quot;">​</a></h3><p>辅助杆宽度、与主图形的间距，必须落在「空中像低于胶阈值」的一侧。太宽或太近会印出残影、甚至桥接；太远则等效没有邻居。这是掩模规则（MRC）与可印性检查的交：SRAF 是物体透过率的一部分，却不是设计层上的器件图形。</p><p><span class="marginnote">SRAF 在晶圆上不应作为独立线条存在。把辅助杆画进 GDS 的器件层当真线，是把 OPC 装饰和电学多边形混层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规则型：按主图形宽度与局部密度查表，在两侧放一条或两根散射条，宽度低于分辨率。模型型：在 OPC 循环外（或耦合）优化杆的位置与宽度，目标是 PV-band 或孤立–密线的剂量/焦点交。Liebchen 一类工作把放置写成受 MRC 与「不得印出」约束的优化，而不是手画装饰。</p><p>掩模类型：二元或 att 版上最常见；交替版上杆的相位归属会与 0/π 染色打架，要额外规则。照明一换（偶极变环带），杆的最优位置就变，必须与光瞳绑定。</p><h3 id="与-opc-主循环的分工" tabindex="-1">与 OPC 主循环的分工 <a class="header-anchor" href="#与-opc-主循环的分工" aria-label="Permalink to &quot;与 OPC 主循环的分工&quot;">​</a></h3><p>主循环挪的是目标边，让边缘放置误差收敛。SRAF 改的是邻域算子本身：先把孤立环境改密，再让主边微调。只跑主循环、不放杆，等于在错误的 TCC 邻域里修 CD。评价必须看工艺窗口带，不能只看名义剂量下轮廓好看。</p>',14)),(e(),n(h,null,{default:r(()=>[p(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISO%5B%22%E5%AD%A4%E7%AB%8B%E7%BA%BF%20%E6%97%A0%E9%82%BB%E5%B1%85%22%5D%20--%3E%20WIN%5B%22%E7%84%A6%E6%B7%B1%E4%B8%8E%E5%89%82%E9%87%8F%E7%AA%97%E5%85%88%E5%85%B3%22%5D%0A%20%20SRAF%5B%22%E4%BA%9A%E5%88%86%E8%BE%A8%E8%BE%85%E5%8A%A9%E6%9D%86%22%5D%20--%3E%20ENV%5B%22%E4%BC%AA%E8%A3%85%E5%AF%86%E7%8E%AF%E5%A2%83%22%5D%0A%20%20ENV%20--%3E%20NOPRINT%5B%22%E8%87%AA%E8%BA%AB%E4%BD%8E%E4%BA%8E%E9%98%88%E5%80%BC%22%5D%0A%20%20ENV%20--%3E%20OPC%5B%22%E4%B8%BB%E8%BE%B9%E5%86%8D%E4%BF%AE%20EPE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>细杆向掩模频谱注入高频与旁瓣能量，投影光瞳滤掉更高的级，残留部分改变主图形附近的背景与斜率（NILS）。焦点一漂，有邻居的空中像比真孤立更稳，于是孤立线的 DOF 向密线靠拢。这与 alt-PSM 不同：相移改的是相邻开口的相位；SRAF 改的是振幅型邻域，通常不要求 2-染色。</p><p>MEF 在细杆上很大：掩模 CD 一点误差，杆可能从「不印」变成「印出」。写入与检测要把 SRAF 当临界小特征，而不是当可忽略的装饰。多层不要共用 SRAF 规则表。</p><p>疏密并存时，辅助杆让孤立线的最佳剂量向密阵列靠拢，E–D 重叠才打得开。只把孤立线加宽到与密线同一 CD，焦深仍按单开口走，窗口交还是孤立图形说了算。</p><p><span class="marginnote">接触孔的辅助往往是二维小块或环形碎片，不是栅极两侧的长杆。孔层照搬线层 scattering bar 间距，会在对角方向造旁瓣。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SRAF 不替代浸没，也不替代多重图形：它救的是单次曝光里疏密窗口交，救不了 \\(k_1\\lt 0.25\\) 的节距。ILT 可以长出曲边助条，思想同类，写入与 MRC 另一套，本课不改写成逆光刻。EUV 上辅助图形仍存在，但阴影与随机效应让「不印」边界更毒，规则不能从 193 nm 薄屏直接复制。</p><p>本课不给辅助杆宽度的宇宙常数。具体纳米数随 \\(\\lambda\\)、\\(\\mathrm{NA}\\)、胶对比与光瞳变。出处停在 Mack 的 RET 框架与 Liebchen 等对放置优化的公开计算光刻工作。</p><p><span class="marginnote">细杆最先打破 Kirchhoff：宽度接近吸收体厚度时，透过不再等于面积比。后课 M3D 会把这笔收回；本课允许薄屏当零阶。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SRAF 给孤立 / 半孤立伪装密环境，自身设计为印不出。</li><li>与 alt-PSM 的相位染色分工：一个改邻域振幅，一个改相邻相位。</li><li>放置受 MRC 与可印性约束，须与光瞳、OPC 绑定。</li><li>细杆 MEF 高，掩模 CD 误差会让杆印出。</li><li>三维电磁下一课起算；本课薄屏零阶。</li><li>出处：Mack 对 scattering bars；Liebchen 等 SRAF 放置与约束优化的计算光刻表述。</li></ul>',11))])}const u=s(A,[["render",d]]);export{b as __pageData,u as default};
